/** Read only the exact six-digit fragment generated by MealQ emails. */
export function otpFromFragment(fragment) {
  if (typeof fragment !== "string" || fragment.length !== 12) return null;
  return fragment.match(/^#code=(\d{6})$/)?.[1] || null;
}

/** Keep router history state, but remove the fragment and any unexpected query. */
export function clearCopyOtpUrl(history, location) {
  if (!location.hash && !location.search) return;
  history.replaceState(history.state, "", location.pathname);
}

/** Called only from an explicit button click; no permission prompt on page load. */
export async function copyOtp(code, clipboard) {
  if (typeof code !== "string" || code.length !== 6 || !/^\d{6}$/.test(code)) return "invalid";
  if (typeof clipboard?.writeText !== "function") return "unsupported";
  try {
    await clipboard.writeText(code);
    return "copied";
  } catch {
    return "failed";
  }
}
